<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { addressesApi } from '../api/addresses'
import { userWorkOrdersApi, workOrderStatuses, workOrderTypes, type WorkOrderRecord } from '../api/workOrders'
const rows=ref<WorkOrderRecord[]>([]), addresses=ref<any[]>([]), selected=ref<WorkOrderRecord|null>(null), error=ref(''), busy=ref(false)
const form=reactive({type:String(location.hash.match(/type=([^&]+)/)?.[1]||'repair'),title:'',description:'',addressId:'',appointmentTime:'',requestId:crypto.randomUUID()})
const q=reactive({page:1,size:10,keyword:'',status:'',type:''})
async function load(){ try{ const r=await userWorkOrdersApi.list(q); rows.value=r.list }catch(e){error.value=e instanceof Error?e.message:'加载失败'} }
async function submit(){ if(!form.addressId||!form.title||!form.description||!form.appointmentTime){error.value='请完整填写预约信息';return}; busy.value=true; try{ selected.value=await userWorkOrdersApi.create({...form,appointmentTime:form.appointmentTime.replace('T',' ')}); await load(); form.requestId=crypto.randomUUID(); error.value='' }catch(e){error.value=e instanceof Error?e.message:'提交失败'}finally{busy.value=false} }
async function cancel(row:WorkOrderRecord){const remark=window.prompt('请输入取消原因'); if(!remark)return; busy.value=true; try{await userWorkOrdersApi.cancel(row.id,remark); await load()}catch(e){error.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false}}
onMounted(async()=>{addresses.value=await addressesApi.list(); if(addresses.value[0]) form.addressId=addresses.value[0].id; await load()})
</script>
<template><header class="page-heading"><span class="eyebrow">SERVICE ORDERS</span><h1>我的工单</h1><p>预约安装、维修和安全检查，查看处理进度。</p></header><p v-if="error" class="inline-notice">{{error}}</p><section class="panel" style="padding:20px"><h2>提交服务预约</h2><form class="aftersale-form" @submit.prevent="submit"><select v-model="form.type"><option v-for="(v,k) in workOrderTypes" :value="k">{{v}}</option></select><input v-model="form.title" maxlength="200" placeholder="服务标题"/><textarea v-model="form.description" maxlength="5000" rows="3" placeholder="问题描述"/><select v-model="form.addressId"><option value="" disabled>选择服务地址</option><option v-for="a in addresses" :value="a.id">{{a.receiver}} {{a.phone}} · {{a.detail}}</option></select><input v-model="form.appointmentTime" type="datetime-local"/><button class="button" :disabled="busy">{{busy?'提交中…':'提交预约'}}</button></form></section><div class="aftersale-tools"><select v-model="q.status" @change="load"><option value="">全部状态</option><option v-for="(v,k) in workOrderStatuses" :value="k">{{v}}</option></select><button class="button secondary" @click="load">刷新</button></div><article v-for="row in rows" :key="row.id" class="panel aftersale-card"><strong>{{row.workOrderNo}} · {{workOrderTypes[row.type]}}</strong><p>{{row.title}} · {{workOrderStatuses[row.status]}}</p><p>预约：{{row.appointmentTime||'—'}}</p><button v-if="['pending','accepted'].includes(row.status)" class="button secondary" @click="cancel(row)">取消工单</button></article></template>
